import{_ as o,l as n,o as e,c as s,v as r,p as l,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"值函数迭代与策略迭代","description":"","frontmatter":{"title":"值函数迭代与策略迭代","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/vfi-pi.md","filePath":"econ/vfi-pi.md","lastUpdated":1789023840000}'),_={name:"econ/vfi-pi.md"};function m(V,a,h,u,P,E){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="值函数迭代与策略迭代" tabindex="-1">值函数迭代与策略迭代 <a class="header-anchor" href="#值函数迭代与策略迭代" aria-label="Permalink to &quot;值函数迭代与策略迭代&quot;">​</a></h1><div class="epigraph"><p>压缩给出唯一不动点，不等于手上已经有 $V$；迭代是把算子变成可算的序列。</p><footer>—— Howard, Dynamic Programming and Markov Processes, 1960；对照 Puterman 的策略改进；Judd, Numerical Methods in Economics, 1998</footer></div><p><a href="/econ/bellman-dp">上一课</a>立住 \\(V=T(V)\\)，并声明算法另写。本课缺口是：<strong>怎么算</strong>。值函数迭代（VFI）反复施加 \\(T\\)；策略迭代（PI）在给定政策上解线性方程再改进政策。不重写压缩定理，不把网格误差写成理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贝尔曼保证不动点存在时，仍要一张表或一组基函数才能在机器上碰到 \\(V\\)。离散状态、有限行动时，\\(T\\) 是有限维 max-plus 运算：从任意有界 \\(V_0\\) 令 \\(V_{n+1}=T(V_n)\\)，压缩比 \\(\\beta\\) 给出线性收敛。Howard：先猜政策 \\(g\\)，解 \\(V=r_g+\\beta P_g V\\)（策略求值），再对每个 \\(s\\) 做贪心改进 \\(g&#39;(s)\\in\\arg\\max_a\\{r+\\beta\\mathrm{E}V\\}\\)，直到政策不再变。缺口是把「有方程」变成「有算法」，而不是再选一次状态。</p><p><span class="marginnote">连续状态要插值或投影。本课只钉 VFI 与 PI 的逻辑；全局逼近的投影法在本课序后部。Rust 的条件选择概率是另一条估计线，不在这里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VFI：选网格 \\(\\{s_i\\}\\)，每个点上对 \\(a\\) 做最大化，用插值读 \\(V(s&#39;)\\)，更新直到 \\(\\lVert V_{n+1}-V_n\\rVert\\) 小于容忍。加速可用 McQueen–Porteus 界或修改政策迭代（每 \\(k\\) 次改进做一次求值）。PI：政策空间有限时有限步精确收敛，每步要解线性系统，状态多时比一次 \\(T\\) 贵。随机冲击用积分或求积节点。借贷约束把 \\(\\arg\\max\\) 变成带不等式的一维搜索，政策在约束处出现 kinks——后课异质主体会反复碰到。</p>',8)),(e(),l(c,null,{default:t(()=>[p(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VFI%5B%22VFI%3A%20%E5%8F%8D%E5%A4%8D%20T%22%5D%20--%3E%20V%5B%22%E9%80%BC%E8%BF%91%20V%22%5D%0A%20%20PI%5B%22PI%3A%20%E6%B1%82%E5%80%BC%E5%86%8D%E6%94%B9%E8%BF%9B%22%5D%20--%3E%20G%5B%22%E6%9C%89%E9%99%90%E6%AD%A5%E5%88%B0%20g%22%5D%0A%20%20V%20--%3E%20POL%5B%22%E8%AF%BB%E5%87%BA%20g%22%5D%0A%20%20G%20--%3E%20POL%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与欧拉方程方法对照：有时直接在欧拉上做时间迭代，不显式存 \\(V\\)。那要求内部解与可微；约束绑定时值函数迭代更老实。本课不把两种对立成教派。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是算子单调加折扣。\\(V_n\\) 从下方（或上方）逼近时，政策也会进入最优政策的邻域——但有限次迭代的 \\(g_n\\) 不必已经最优，只是对当前 \\(V_n\\) 贪心。PI 的求值步把「这条政策的真值」算准，改进步利用贝尔曼的贪心充分性。误差来源是网格、插值、积分与提前停止，不是贝尔曼本身写错。</p><p>代表性个体的光滑凹问题上，VFI 往往够用。一旦分布成为状态，每次 \\(T\\) 都要在测度上操作，直接网格爆炸——那是 Krusell–Smith 用有界感知代替全分布的理由，不是本课提前解掉的。</p><p><span class="marginnote">Judd 强调：算法收敛不等于经济收敛到正确均衡。错误的状态或错误的期望算子会让漂亮的 \\(V\\) 对应错误的模型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准、不估计。连续时间的策略改进有微分方程版本，不在此写。也不把深度学习当新原理：函数逼近可以换基，算子还是 \\(T\\)。局部扰动法下一课之后才出现，那是另一条「不求全局 \\(V\\)」的路。</p><p>后课默认：说到「解贝尔曼」，指 VFI/PI 或等价的欧拉迭代，已经知道网格与 kinks。下一课补上：即使不求 \\(V\\)，欧拉加横截也能刻画内部路径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VFI 迭代 \\(T\\)；PI 在政策上求值再贪心改进。</li><li>约束与 kinks 时显式值函数更稳；光滑内部解可用欧拉迭代。</li><li>算法误差与模型误差要分开。</li><li>出处：Howard 1960；Judd, <em>Numerical Methods in Economics</em>, 1998。</li></ul>',10))])}const I=o(_,[["render",m]]);export{T as __pageData,I as default};
